# lending-desk

The lending desk service of the city library's branches: checkouts, returns, renewals, holds, fees,
notices to members, and the self-check machines.

Plain Node.js ES modules, no dependencies. Node.js 22 or later.

```sh
npm test    # runs every test in test/
npm start   # serves the API on port 8080, with demo data
```
{
  "name": "lending-desk",
  "version": "0.4.0",
  "private": true,
  "type": "module",
  "description": "The lending desk service of the city library: checkouts, returns, renewals, holds, fees and notices.",
  "scripts": {
    "start": "node lib/server/http.js",
    "test": "node --test"
  }
}
import { daysBetween } from '../helpers/dates.js';
import { DAILY_LATE_FEE_CENTS, GRACE_DAYS } from './schedule.js';

/** Returns the late fee in cents for a loan returned on `returnedOn`, 0 when none is due. */
export function assessLateFee({ loan, item, member, returnedOn }) {
  if (member.type === 'staff') return 0;
  const daysLate = daysBetween(loan.dueOn, returnedOn);
  if (daysLate <= GRACE_DAYS) return 0;
  return daysLate * DAILY_LATE_FEE_CENTS[item.format];
}
/** A member who owes at least this many cents may not borrow until they pay. */
export const BLOCKING_BALANCE_CENTS = 1000;

/** Returns what a member owes, in cents: the sum of their unpaid fees. */
export function outstandingBalance(store, memberId) {
  return store
    .listFees(memberId)
    .filter((fee) => !fee.paid)
    .reduce((sum, fee) => sum + fee.amountCents, 0);
}
/** Records that a member paid a fee in full at the desk, and returns the paid fee. */
export function payFee(store, feeId, paidOn) {
  const fee = store.getFee(feeId);
  if (fee === undefined) throw new Error(`Unknown fee ${feeId}`);
  if (fee.paid) throw new Error(`Fee ${feeId} is already paid`);
  return store.saveFee({ ...fee, paid: true, paidOn });
}
/** What a day late costs, in cents, by format. */
export const DAILY_LATE_FEE_CENTS = { book: 25, dvd: 100, magazine: 10, laptop: 500 };

/** An item returned at most this many days after its due date costs nothing. */
export const GRACE_DAYS = 1;
/** The reasons a librarian may waive a fee for. */
export const WAIVER_REASONS = ['returned-in-book-drop', 'staff-error', 'hardship'];

/** Waives a fee for one of the allowed reasons, and returns the waived fee. */
export function waiveFee(store, feeId, reason) {
  if (!WAIVER_REASONS.includes(reason)) throw new Error(`Unknown waiver reason ${reason}`);
  const fee = store.getFee(feeId);
  if (fee === undefined) throw new Error(`Unknown fee ${feeId}`);
  return store.saveFee({ ...fee, waivedReason: reason });
}
import { normaliseBarcode } from '../catalog/barcodes.js';
import { assessLateFee } from '../fees/assess.js';
import { holdReadyNotice } from '../holds/notify.js';
import { fulfilNextHold } from '../holds/queue.js';

/**
 * Takes an item back: closes its loan, charges any late fee and readies the next hold for it.
 * Returns { ok: true, loan, feeCents, notice } or { ok: false, reason }; notice is null when
 * nobody was waiting for the item.
 */
export function returnItem(store, { barcode, today }) {
  const item = store.findItemByBarcode(normaliseBarcode(barcode));
  if (item === undefined) return { ok: false, reason: 'unknown-item' };
  const loan = store.findOpenLoan(item.id);
  if (loan === undefined) return { ok: false, reason: 'not-on-loan' };
  const closed = store.saveLoan({ ...loan, returnedOn: today });
  const member = store.getMember(loan.memberId);
  const feeCents = assessLateFee({ loan, item, member, returnedOn: today });
  if (feeCents > 0) {
    store.saveFee({
      memberId: member.id,
      loanId: loan.id,
      amountCents: feeCents,
      paid: false,
      waivedReason: null,
    });
  }
  const hold = fulfilNextHold(store, item.id, today);
  return { ok: true, loan: closed, feeCents, notice: hold === null ? null : holdReadyNotice(store, hold) };
}
import { CARD_YEARS } from '../config/defaults.js';

/** Tells whether a member's library card has expired by `today`. */
export function isCardExpired(member, today) {
  return member.cardExpiresOn < today;
}

/** Returns the member with their card renewed from today for the years their type allows. */
export function renewCard(member, today) {
  const year = Number(today.slice(0, 4)) + CARD_YEARS[member.type];
  return { ...member, cardExpiresOn: `${year}${today.slice(4)}` };
}
